# The MobileNetV2-12 ONNX export from the (Apache-2.0) ONNX Model Zoo, mirrored on the
# Hugging Face Hub. ~13 MB; downloaded once via huggingface_hub and cached like any HF
# model weights (~/.cache/huggingface), the same pattern chatbot.py uses for transformers.
_MODEL_REPO = "onnxmodelzoo/mobilenetv2-12"
_MODEL_FILE = "mobilenetv2-12.onnx"

_IMAGENET_MEAN = (0.485, 0.456, 0.406)
_IMAGENET_STD = (0.229, 0.224, 0.225)

_session = None  # lazily-loaded onnxruntime.InferenceSession, cached across calls


def _load_session():
    """Download (once, cached) and load the ONNX model. Lazy so importing this
    module -- and indah's own test suite -- never requires onnxruntime installed."""
    global _session
    if _session is None:
        from huggingface_hub import hf_hub_download
        from onnxruntime import InferenceSession

        path = hf_hub_download(repo_id=_MODEL_REPO, filename=_MODEL_FILE)
        _session = InferenceSession(path, providers=["CPUExecutionProvider"])
    return _session


def _predict(data: bytes):
    """Decode ``data`` with Pillow, run one onnxruntime inference, and return the
    softmax over all 1000 classes. Everything else in this file builds on this.
    """
    import io

    import numpy as np
    from PIL import Image as PILImage

    image = PILImage.open(io.BytesIO(data)).convert("RGB").resize((224, 224))
    pixels = np.asarray(image, dtype=np.float32) / 255.0
    pixels = (pixels - _IMAGENET_MEAN) / _IMAGENET_STD  # numpy promotes this to float64
    batch = pixels.transpose(2, 0, 1)[np.newaxis, ...].astype(np.float32)  # HWC -> NCHW

    session = _load_session()
    (logits,) = session.run(None, {"input": batch})
    exp = np.exp(logits[0] - logits[0].max())
    return exp / exp.sum()


def classify(data: bytes) -> tuple[str, float]:
    """The top-1 ``(label, confidence)`` for an image's raw bytes, run live on CPU.

    A real GPU model would drop in behind this same signature with the rest of the
    app unchanged - this one is deliberately CPU-only and light enough to run
    per-request on a shared box.
    """
    probs = _predict(data)
    top = int(probs.argmax())
    return IMAGENET_LABELS[top], float(probs[top])


def classify_topk(data: bytes, k: int = 5) -> list[tuple[str, float]]:
    """The top ``k`` ``(label, confidence)`` pairs, most confident first."""
    probs = _predict(data)
    order = probs.argsort()[::-1][:k]
    return [(IMAGENET_LABELS[i], float(probs[i])) for i in order]


# Five sample photos the model reliably gets right, so a first-time visitor sees the
# demo work before trying their own (and possibly stumping it). All public domain,
# from Wikimedia Commons: Giant_panda_(1).jpg (Stolz Gary M, U.S. Fish and Wildlife
# Service), Zebra_(24694097565).jpg (Mussi Katz, CC0), Cat_Close_Up.jpg (CoolKid1993),
# Acoustic_guitar.jpg (Massimo Giuliani), Kermorvan-lighthouse-20060525-020.jpg
# (Ghouston, CC0). Embedded here, not fetched at runtime, for the same reason as
# IMAGENET_LABELS above: the Colab notebook only gets this module's own source text.
_SAMPLES: dict[str, tuple[str, str]] = {
    "panda": (
        "Giant panda",
        "",
    ),
    "zebra": (
        "Zebra",
        "",
    ),
    "cat": (
        "Cat",
        "",
    ),
    "guitar": (
        "Guitar",
        "",
    ),
    "lighthouse": (
        "Lighthouse",
        "",
    ),
}


def _data_uri(file: UploadedFile) -> str:
    """The uploaded image bytes as a data: URI, so the shell can show it back."""
    mime = file.content_type or "image/png"
    return f"data:{mime};base64," + base64.b64encode(file.data).decode("ascii")


def _predictions_chart(predictions: list[tuple[str, float]]):
    """A horizontal bar chart of the top predictions, most confident at the top.
    Matplotlib is lazy-imported here for the same reason onnxruntime/Pillow are:
    importing this module, and indah's own test suite, shouldn't need it installed.
    """
    import matplotlib

    matplotlib.use("Agg")
    from matplotlib.figure import Figure

    fig = Figure(figsize=(4, 2.6))
    ax = fig.add_subplot(111)
    if predictions:
        labels = [label for label, _confidence in reversed(predictions)]
        values = [confidence * 100 for _label, confidence in reversed(predictions)]
        ax.barh(labels, values, color="#b5296b")
        ax.set_xlim(0, 100)
        ax.set_xlabel("Confidence (%)")
        for i, value in enumerate(values):
            ax.text(value + 1.5, i, f"{value:.0f}%", va="center", fontsize=8)
    ax.set_frame_on(False)
    fig.tight_layout()
    return fig


def build_session() -> Session:
    """A fresh per-viewer graph: get an image in, classify it, show the result."""
    preview: Signal[str] = Signal("")
    result: Signal[str] = Signal("")
    predictions: Signal[list] = Signal([])
    report: Signal = Signal(None)
    busy: Signal[bool] = Signal(False)

    async def _run(data: bytes, preview_uri: str, source: str) -> None:
        busy.set(True)
        result.set("")
        predictions.set([])
        report.set(None)
        preview.set(preview_uri)
        # onnxruntime inference is synchronous CPU work; run it off the event loop
        # so it never blocks the UI, the same guarantee chatbot.py's
        # asyncio.to_thread call gives its (also synchronous, thread-run) generation.
        top = await asyncio.to_thread(classify_topk, data, 5)
        predictions.set(top)
        label, confidence = top[0]
        result.set(f"Prediction: **{label}**  \nConfidence: **{confidence:.0%}**")
        ranked = "\n".join(f"  {i + 1}. {lbl}: {conf:.2%}" for i, (lbl, conf) in enumerate(top))
        summary = (
            f"source: {source}\n"
            f"prediction: {label}\n"
            f"confidence: {confidence:.2f}\n\n"
            f"top {len(top)}:\n{ranked}\n"
        )
        report.set(
            DownloadFile(summary.encode(), filename="prediction.txt", media_type="text/plain")
        )
        busy.set(False)

    async def on_upload(file: UploadedFile) -> None:
        await _run(file.data, _data_uri(file), f"uploaded file '{file.filename}'")

    async def on_sample(slug: str) -> None:
        if busy.value:
            return
        label, b64 = _SAMPLES[slug]
        preview_uri = f"data:image/jpeg;base64,{b64}"
        await _run(base64.b64decode(b64), preview_uri, f"sample photo '{label}'")

    sample_buttons = Row(
        children=[
            Button(label, on_click=(lambda s=slug: on_sample(s)), variant="ghost")
            for slug, (label, _b64) in _SAMPLES.items()
        ],
        gap="0.5rem",
    )

    return Session(
        Column(
            children=[
                Text(
                    "# Image classifier\n\n"
                    "Click a sample photo, or upload your own, and a real MobileNetV2 "
                    "model predicts what's in it - live, on CPU. Each tab is its own "
                    "session, so your result stays private to it.",
                    markdown=True,
                ),
                Card(
                    title="Input",
                    children=[
                        Text("Try a sample:"),
                        sample_buttons,
                        Upload(on_upload, accept="image/*", label="Or upload your own"),
                        Spinner(active=busy, label="Classifying..."),
                    ],
                ),
                Card(
                    title="Result",
                    children=[
                        Row(
                            children=[
                                Image(preview, alt="the classified image"),
                                Plot(
                                    lambda: _predictions_chart(predictions.value),
                                    alt="top predictions",
                                ),
                            ],
                            gap="1rem",
                        ),
                        Text(lambda: result.value or "_No prediction yet._", markdown=True),
                        Download(report, label="Download report", filename="prediction.txt"),
                    ],
                ),
            ]
        )
    )


# Module-level ASGI app for hosting.
app = create_app(session_factory=build_session)


if __name__ == "__main__":
    indah.launch(app)
